window.ToyData.register("exercises-physics.json","[{\"type\":\"self\",\"prompt\":\"刘翔在2004雅典奥运会上完成110 m跨栏的时间为12.91 s，求他的平均速度。\",\"answer\":\"v = 110 / 12.91 ≈ 8.52 m/s\",\"explanation\":\"利用平均速度定义，代入总路程与总时间计算。\",\"id\":\"cnp_k8acpt12_q124002\",\"topicId\":\"cnp_k8acpt12\",\"linkedTopicIds\":[\"cnp_k8acpt12\",\"cnp_k8askl4\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_8a_rjb_exe2\",\"sourceBook\":\"八年级上册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"在测量平均速度的实验中，应该用什么测量路程，用什么测量时间，并用什么公式求出平均速度？\",\"answer\":\"用刻度尺测量路程，用停表测量时间，用公式 v = s / t 求平均速度。\",\"id\":\"cnp_k8acpt12_q124003\",\"topicId\":\"cnp_k8acpt12\",\"linkedTopicIds\":[\"cnp_k8acpt12\",\"cnp_k8askl5\",\"cnp_k8askl6\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_8a_rjb_exe3\",\"sourceBook\":\"八年级上册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"某种昆虫的翅在2 s内做了700次振动，频率是多少？人类能听到吗？\",\"answer\":\"频率为350 Hz，处于可听范围内，人类能听到。\",\"id\":\"cnp_k8acpt24_q124005\",\"topicId\":\"cnp_k8acpt24\",\"linkedTopicIds\":[\"cnp_k8acpt24\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_8a_rjb_exe5\",\"sourceBook\":\"八年级上册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"“光年”是什么物理量的单位？\",\"answer\":\"光年是距离单位，表示光在真空中一年内传播的距离。\",\"id\":\"cnp_k8acpt72_q124008\",\"topicId\":\"cnp_k8acpt72\",\"linkedTopicIds\":[\"cnp_k8acpt72\",\"cnp_k8askl15\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_8a_rjb_exe8\",\"sourceBook\":\"八年级上册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"光与镜面成30°角射在平面镜上，反射角是多大？\",\"answer\":\"入射角 = 60°，反射角 = 60°。\",\"explanation\":\"光与镜面夹角为30°，则光与法线夹角为60°，根据反射定律反射角=入射角。\",\"id\":\"cnp_010_q124009\",\"topicId\":\"cnp_010\",\"linkedTopicIds\":[\"cnp_010\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_8a_rjb_exe9\",\"sourceBook\":\"八年级上册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"为什么太阳光经过三棱镜后会出现彩色光带？\",\"answer\":\"因为白光由各种色光组成，通过三棱镜后不同色光发生不同程度的折射，从而分解形成彩色光带。\",\"explanation\":\"考察光的色散原理。\",\"id\":\"cnp_k8acpt89_q124011\",\"topicId\":\"cnp_k8acpt89\",\"linkedTopicIds\":[\"cnp_k8acpt89\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_8a_rjb_exe11\",\"sourceBook\":\"八年级上册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"照相机成像时，物体较远，照相机底片上形成的像是什么性质？\",\"answer\":\"缩小、倒立的实像。\",\"explanation\":\"物距较大时，凸透镜成缩小、倒立的实像。\",\"id\":\"cnp_k8acpt103_q124013\",\"topicId\":\"cnp_k8acpt103\",\"linkedTopicIds\":[\"cnp_k8acpt103\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_8a_rjb_exe13\",\"sourceBook\":\"八年级上册\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"一块质量为100 g的冰熔化成水后，质量（ ）。\",\"answer\":\"A\",\"choices\":[{\"key\":\"A\",\"text\":\"仍是100 g\"},{\"key\":\"B\",\"text\":\"大于100 g\"},{\"key\":\"C\",\"text\":\"小于100 g\"}],\"sourceAnswer\":\"A\",\"id\":\"cnp_k8acpt126_q124014\",\"topicId\":\"cnp_k8acpt126\",\"linkedTopicIds\":[\"cnp_k8acpt126\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_8a_rjb_exe14\",\"sourceBook\":\"八年级上册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"汽车突然刹车时，乘客身体前倾的原因是什么？\",\"answer\":\"乘客身体具有惯性，车体停止时上半身仍保持原来的运动状态，因此身体前倾。\",\"explanation\":\"考察惯性的定义及生活实例理解。\",\"id\":\"cnp_k8bcpt24_q125003\",\"topicId\":\"cnp_k8bcpt24\",\"linkedTopicIds\":[\"cnp_k8bcpt24\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_8b_rjb_exe3\",\"sourceBook\":\"八年级下册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"跳伞运动员匀速下降时，若人和伞所受的总重力是1000N，阻力的大小和方向是什么？\",\"answer\":\"阻力大小为1000N，方向竖直向上。\",\"explanation\":\"匀速直线运动处于力的平衡状态，根据二力平衡条件，阻力需与重力大小相等、方向相反。\",\"id\":\"cnp_016_q125004\",\"topicId\":\"cnp_016\",\"linkedTopicIds\":[\"cnp_016\",\"cnp_k8bskl3\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_8b_rjb_exe4\",\"sourceBook\":\"八年级下册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"水平桌面上放一本书，重力为3N，与桌面接触面积为5×10⁻² m²，求书对桌面的压强。\",\"answer\":\"60 Pa\",\"explanation\":\"利用公式 p=F/S = 3N ÷ 5×10⁻² m² = 60 Pa。\",\"id\":\"cnp_018_q125006\",\"topicId\":\"cnp_018\",\"linkedTopicIds\":[\"cnp_018\",\"cnp_k8bskl5\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_8b_rjb_exe6\",\"sourceBook\":\"八年级下册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"大石头质量为6t，起重机在15s内将大石头匀速提升1m，求起重机提升大石头的功率。g取10 N/kg。\",\"answer\":\"4×10^3 W\",\"explanation\":\"先根据匀速提升求拉力F=mg，再计算做功W=Fs，最后用P=W/t求功率。\",\"id\":\"cnp_024_q125013\",\"topicId\":\"cnp_024\",\"linkedTopicIds\":[\"cnp_024\",\"cnp_k8bskl12\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_8b_rjb_exe13\",\"sourceBook\":\"八年级下册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"起重机把质量为0.5t的重物匀速提升3m，电动机做功为3.4×10^4 J，求机械效率。（g=10N/kg）\",\"answer\":\"44%\",\"id\":\"cnp_k8bcpt96_q125018\",\"topicId\":\"cnp_k8bcpt96\",\"linkedTopicIds\":[\"cnp_k8bcpt96\",\"cnp_k8bskl14\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_8b_rjb_exe18\",\"sourceBook\":\"八年级下册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"有两段导线A和B，在相同电压下，通过A的电流较大，通过B的电流较小，哪段导线电阻大？\",\"answer\":\"B的电阻大。\",\"explanation\":\"相同电压下电流小的导线电阻大。\",\"id\":\"cnp_039_q129012\",\"topicId\":\"cnp_039\",\"linkedTopicIds\":[\"cnp_039\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_9_rjb_exe12\",\"sourceBook\":\"九年级\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"一辆汽车的车灯接在 12V 电源两端，灯丝电阻为 30Ω，求通过灯丝的电流。\",\"answer\":\"0.4A\",\"id\":\"cnp_043_q129015\",\"topicId\":\"cnp_043\",\"linkedTopicIds\":[\"cnp_043\",\"cnp_k9skl12\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_9_rjb_exe15\",\"sourceBook\":\"九年级\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"一根60Ω的电阻丝接在36V电源两端，在5分钟内共产生多少热量？\",\"answer\":\"6480J\",\"explanation\":\"先利用欧姆定律求I=U/R=0.6A，再代入Q=I^2Rt计算。\",\"id\":\"cnp_044_q129021\",\"topicId\":\"cnp_044\",\"linkedTopicIds\":[\"cnp_044\",\"cnp_k9skl17\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_9_rjb_exe21\",\"sourceBook\":\"九年级\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"某物体受到一个32N水平向右的力和一个44N竖直向上的力，通过作图求出合力大小和方向。\",\"answer\":\"合力大小约为54.4N，方向与水平右向夹角约54°。\",\"explanation\":\"利用平行四边形定则作图测量。\",\"id\":\"cnp_kbx1cpt54_q131011\",\"topicId\":\"cnp_kbx1cpt54\",\"linkedTopicIds\":[\"cnp_kbx1cpt54\",\"cnp_kbx1skl16\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_bx1_rjb_exe11\",\"sourceBook\":\"必修一\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"运动员以3.4 m/s速度投掷冰壶，动摩擦因数为0.02，求冰壶滑行距离。g=10 m/s²。\",\"answer\":\"28.9 m\",\"explanation\":\"受力只有滑动摩擦力 Ff=μmg，利用 a=Ff/m 得 a=-0.2 m/s²；代入 v²-v0²=2ax 求得滑行距离。\",\"id\":\"cnp_h016_q131015\",\"topicId\":\"cnp_h016\",\"linkedTopicIds\":[\"cnp_h016\",\"cnp_017\",\"cnp_kbx1cpt76\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_bx1_rjb_exe15\",\"sourceBook\":\"必修一\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"将一个物体以10 m/s 的速度从10 m 的高度水平抛出，求落地时速度方向与水平地面的夹角θ（g=10 m/s²）。\",\"answer\":\"θ = 55°\",\"explanation\":\"根据vx=v0=10 m/s，vy=√(2gh)=14.1 m/s，tanθ=vy/vx=1.41，θ≈55°。\",\"id\":\"cnp_kbx2cpt15_q132002\",\"topicId\":\"cnp_kbx2cpt15\",\"linkedTopicIds\":[\"cnp_kbx2cpt15\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_bx2_rjb_exe2\",\"sourceBook\":\"必修二\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"圆锥摆中，当细绳与竖直方向的夹角为θ时，小球的向心加速度大小是多少？\",\"answer\":\"a_n = g tanθ\",\"explanation\":\"根据受力分析得F_n = m g tanθ，再根据a_n = F_n/m得到g tanθ。\",\"id\":\"cnp_h026_q132004\",\"topicId\":\"cnp_h026\",\"linkedTopicIds\":[\"cnp_h026\",\"cnp_kbx2skl6\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_bx2_rjb_exe4\",\"sourceBook\":\"必修二\",\"difficulty\":\"standard\"},{\"type\":\"self\",\"prompt\":\"一个质量为150kg 的雪橇，受到大小500N、与水平方向成37°的拉力，在水平地面上移动5m，阻力为100N。求总功。\",\"answer\":\"总功为1500J。\",\"explanation\":\"找出与位移方向平行的分力做功并与阻力功相加。\",\"id\":\"cnp_023_q132009\",\"topicId\":\"cnp_023\",\"linkedTopicIds\":[\"cnp_023\",\"cnp_kbx2skl11\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_bx2_rjb_exe9\",\"sourceBook\":\"必修二\",\"difficulty\":\"standard\"},{\"type\":\"self\",\"prompt\":\"电场中两个电势不同的等势面能不能相交？说明理由。\",\"answer\":\"不能相交。若相交，则交线上同一点同时属于两个等势面，会被赋予两个不同的电势，矛盾。\",\"explanation\":\"利用等势面的定义：同一等势面上电势相同；用反证思路说明相交将导致同一点电势不唯一。\",\"id\":\"cnp_kbx3cpt58_q133013\",\"topicId\":\"cnp_kbx3cpt58\",\"linkedTopicIds\":[\"cnp_kbx3cpt58\",\"cnp_kbx3skl13\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_bx3_rjb_exe13\",\"sourceBook\":\"必修三\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"手电筒中的干电池给小灯泡供电时，在某次接通开关的10 s内通过某一横截面的电荷量为3 C，则电流是多少？\",\"answer\":\"I = q/t = 3 C / 10 s = 0.30 A。\",\"explanation\":\"直接应用电流定义式I=q/t。\",\"id\":\"cnp_kbx3cpt92_q133020\",\"topicId\":\"cnp_kbx3cpt92\",\"linkedTopicIds\":[\"cnp_kbx3cpt92\",\"cnp_kbx3skl22\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_bx3_rjb_exe20\",\"sourceBook\":\"必修三\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"电阻丝的电阻为R，接入电路的有效长度为l，直径为d。写出该金属丝电阻率ρ的计算式（用R、l、d表示）。\",\"answer\":\"ρ=SR/l，其中S=πd^2/4，所以ρ=πd^2R/(4l)。\",\"explanation\":\"由电阻率定义关系ρ=SR/l，圆截面面积S=πd^2/4，代入即可。\",\"id\":\"cnp_kbx3cpt100_q133024\",\"topicId\":\"cnp_kbx3cpt100\",\"linkedTopicIds\":[\"cnp_kbx3cpt100\",\"cnp_kbx3cpt108\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_bx3_rjb_exe24\",\"sourceBook\":\"必修三\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"用刻度尺测电阻丝直径误差较大。若将电阻丝在圆柱体上紧密缠绕N圈，测得总宽度为L（刻度尺读数），则电阻丝直径d应如何表达？\",\"answer\":\"d=L/N（需保证缠绕紧密且圈与圈无间隙）。\",\"explanation\":\"累积法用总宽度平均到每一圈，等效为单根直径。\",\"id\":\"cnp_kbx3cpt109_q133025\",\"topicId\":\"cnp_kbx3cpt109\",\"linkedTopicIds\":[\"cnp_kbx3cpt109\",\"cnp_kbx3skl30\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_bx3_rjb_exe25\",\"sourceBook\":\"必修三\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"用多用电表测量直流电流时，电流应该从哪支表笔流入多用电表？测量直流电压时，哪支表笔应接在电势较高的一端？\",\"answer\":\"测直流电流时电流应从红表笔流入多用电表；测直流电压时红表笔应接在电势较高的一端（黑表笔接电势较低的一端）。\",\"id\":\"cnp_kbx3cpt134_q133028\",\"topicId\":\"cnp_kbx3cpt134\",\"linkedTopicIds\":[\"cnp_kbx3cpt134\",\"cnp_kbx3cpt133\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_bx3_rjb_exe28\",\"sourceBook\":\"必修三\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"家用微波炉的微波频率为2450 MHz，它的波长是多少?\",\"answer\":\"λ=c/f=3.0×10^8/(2.450×10^9)≈1.22×10^-1 m，约0.122 m（12.2 cm）。\",\"explanation\":\"将MHz换算为Hz，用c=λf求λ。\",\"id\":\"cnp_kbx3cpt191_q133042\",\"topicId\":\"cnp_kbx3cpt191\",\"linkedTopicIds\":[\"cnp_kbx3cpt191\",\"cnp_kbx3skl48\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_bx3_rjb_exe42\",\"sourceBook\":\"必修三\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"变化的磁场和变化的电场形成不可分割的统一体——电磁场，它会由近及远地向外传播，它的传播需要介质吗？它传播的速度是多少？\",\"answer\":\"不需要介质，可在真空中传播；在真空中的传播速度c=3×10^8 m/s（等于光速）。\",\"explanation\":\"电磁波与声波、水波不同，不依赖介质；速度为光速。\",\"id\":\"cnp_kbx3cpt187_q133043\",\"topicId\":\"cnp_kbx3cpt187\",\"linkedTopicIds\":[\"cnp_kbx3cpt187\",\"cnp_kbx3cpt188\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_bx3_rjb_exe43\",\"sourceBook\":\"必修三\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"一个质量为 0.1 kg 的钢球以 6 m/s 的速度向右撞墙弹回，以 6 m/s 向左运动。求碰撞前后动量的变化量。\",\"answer\":\"动量变化量为 -1.2 kg·m/s，方向向左。\",\"explanation\":\"先选定正方向，以 p' - p 求动量变化量。\",\"id\":\"cnp_kxzxbx1cpt1_q141001\",\"topicId\":\"cnp_kxzxbx1cpt1\",\"linkedTopicIds\":[\"cnp_kxzxbx1cpt1\",\"cnp_kxzxbx1skl1\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_xzxbx1_rjb_exe1\",\"sourceBook\":\"选择性必修一\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"一个质量为 0.18 kg 的垒球以 25 m/s 的速度飞向球棒，被击打后以 45 m/s 的速度反向飞回，作用时间为 0.002 s。求球棒对垒球的平均作用力大小。\",\"answer\":\"6300 N\",\"explanation\":\"利用动量定理计算平均力：F = Δp/Δt。\",\"id\":\"cnp_kxzxbx1cpt5_q141002\",\"topicId\":\"cnp_kxzxbx1cpt5\",\"linkedTopicIds\":[\"cnp_kxzxbx1cpt5\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_xzxbx1_rjb_exe2\",\"sourceBook\":\"选择性必修一\",\"difficulty\":\"standard\"},{\"type\":\"self\",\"prompt\":\"一辆质量为 1.8×10^4 kg 的货车以 2 m/s 的速度运动，碰上一辆质量为 2.2×10^4 kg 的静止货车，它们碰撞后结合在一起，求碰撞后的速度。\",\"answer\":\"0.9 m/s\",\"explanation\":\"将两车作为系统，外力合为零，使用动量守恒定律求解 v = m1 v1 / (m1 + m2)。\",\"id\":\"cnp_kxzxbx1cpt10_q141003\",\"topicId\":\"cnp_kxzxbx1cpt10\",\"linkedTopicIds\":[\"cnp_kxzxbx1cpt10\",\"cnp_kxzxbx1skl4\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_xzxbx1_rjb_exe3\",\"sourceBook\":\"选择性必修一\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"章鱼喷射水流向后运动，从而身体向前游动，这一现象体现了什么物理原理？\",\"answer\":\"体现了反冲现象，根据动量守恒定律，水向后喷出，章鱼获得向前的反冲速度。\",\"explanation\":\"水的动量向后，章鱼的动量向前，使系统总动量为0。\",\"id\":\"cnp_kxzxbx1cpt17_q141007\",\"topicId\":\"cnp_kxzxbx1cpt17\",\"linkedTopicIds\":[\"cnp_kxzxbx1cpt17\",\"cnp_kxzxbx1skl8\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_xzxbx1_rjb_exe7\",\"sourceBook\":\"选择性必修一\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"一个理想单摆周期为T，若自由落体加速度变为原来的1/2，周期变为多少？\",\"answer\":\"T' = √2 T\",\"explanation\":\"由T=2π√(l/g)，当g→g/2，T'=2π√(l/(g/2))=√2 T。\",\"id\":\"cnp_kxzxbx1cpt33_q141010\",\"topicId\":\"cnp_kxzxbx1cpt33\",\"linkedTopicIds\":[\"cnp_kxzxbx1cpt33\",\"cnp_kxzxbx1skl11\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_xzxbx1_rjb_exe10\",\"sourceBook\":\"选择性必修一\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"在用双缝干涉测量光的波长的实验中，为什么不直接测 Δx，而要通过测 n 条条纹的间距求出 Δx？\",\"answer\":\"因为单次测量 Δx 读数误差较大，测多条条纹的总距离可减小随机误差，提高测量精度。\",\"explanation\":\"考察学生理解误差控制方法。\",\"id\":\"cnp_kxzxbx1skl17_q141019\",\"topicId\":\"cnp_kxzxbx1skl17\",\"linkedTopicIds\":[\"cnp_kxzxbx1skl17\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_xzxbx1_rjb_exe19\",\"sourceBook\":\"选择性必修一\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"电子的速率 v = 3.0 × 10^6 m/s，沿垂直于磁场方向射入 B = 0.10 T 的磁场中，它受到的洛伦兹力多大？\",\"answer\":\"F = q v B = (1.6×10^-19 C)(3.0×10^6 m/s)(0.10 T) = 4.8×10^-14 N。\",\"id\":\"cnp_kxzxbx2cpt4_q142001\",\"topicId\":\"cnp_kxzxbx2cpt4\",\"linkedTopicIds\":[\"cnp_kxzxbx2cpt4\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_xzxbx2_rjb_exe1\",\"sourceBook\":\"选择性必修二\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"有一个1000匝的线圈，在0.4 s内通过它的磁通量从0.02 Wb增加到0.09 Wb，求线圈中的感应电动势。\",\"answer\":\"E = n ΔΦ/Δt = 1000 × (0.09 - 0.02)/0.4 = 175 V\",\"id\":\"cnp_kxzxbx2cpt21_q142006\",\"topicId\":\"cnp_kxzxbx2cpt21\",\"linkedTopicIds\":[\"cnp_kxzxbx2cpt21\",\"cnp_kxzxbx2skl6\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_xzxbx2_rjb_exe6\",\"sourceBook\":\"选择性必修二\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"某机床把380V降到36V，如果原线圈1440匝，求副线圈匝数。\",\"answer\":\"副线圈匝数约为136匝。\",\"explanation\":\"利用 U1/U2 = n1/n2，n2 = n1 * U2 / U1 = 1440 * 36 / 380\",\"id\":\"cnp_kxzxbx2cpt48_q142007\",\"topicId\":\"cnp_kxzxbx2cpt48\",\"linkedTopicIds\":[\"cnp_kxzxbx2cpt48\",\"cnp_k8bskl8\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_xzxbx2_rjb_exe7\",\"sourceBook\":\"选择性必修二\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"采用 110 kV 高压输电，输送电功率为 4800 kW 的电能，求输电导线中的电流。\",\"answer\":\"I = P/U = 4800 kW / 110 kV ≈ 43.6 A。\",\"explanation\":\"使用公式 P=UI，体现高压输电降低电流。\",\"id\":\"cnp_kxzxbx2cpt53_q142008\",\"topicId\":\"cnp_kxzxbx2cpt53\",\"linkedTopicIds\":[\"cnp_kxzxbx2cpt53\",\"cnp_kxzxbx2skl9\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_xzxbx2_rjb_exe8\",\"sourceBook\":\"选择性必修二\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"我国第一颗人造卫星用20.009 MHz和19.995 MHz的电磁波发送信号，求这两种电磁波的波长。\",\"answer\":\"λ1≈15.0 m，λ2≈15.0 m（使用公式λ=c/f）\",\"explanation\":\"利用电磁波波长公式λ=c/f，代入频率求解。\",\"id\":\"cnp_kxzxbx2cpt66_q142011\",\"topicId\":\"cnp_kxzxbx2cpt66\",\"linkedTopicIds\":[\"cnp_kxzxbx2cpt66\",\"cnp_kxzxbx2cpt63\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_xzxbx2_rjb_exe11\",\"sourceBook\":\"选择性必修二\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"能够引起人的视觉的电磁波波长范围是多少？\",\"answer\":\"约400~760 nm。\",\"id\":\"cnp_kxzxbx2cpt71_q142012\",\"topicId\":\"cnp_kxzxbx2cpt71\",\"linkedTopicIds\":[\"cnp_kxzxbx2cpt71\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_xzxbx2_rjb_exe12\",\"sourceBook\":\"选择性必修二\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"在一个密闭容器内有一滴15℃的水，过一段时间后蒸发成水蒸气，温度仍为15℃。它的内能是否发生变化？为什么？\",\"answer\":\"内能增加。因为水变为水蒸气后分子间距离增大，分子势能增大，尽管温度不变，但内能仍上升。\",\"explanation\":\"考查内能由动能和势能组成，蒸发过程主要改变分子势能。\",\"id\":\"cnp_033_q143002\",\"topicId\":\"cnp_033\",\"linkedTopicIds\":[\"cnp_033\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_xzxbx3_rjb_exe2\",\"sourceBook\":\"选择性必修三\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"压缩汽缸里的空气，对空气做了900 J的功，同时汽缸向外散热210 J，空气的内能改变多少？\",\"answer\":\"ΔU = Q + W = -210 J + 900 J = 690 J，内能增加690 J。\",\"id\":\"cnp_kxzxbx3cpt55_q143005\",\"topicId\":\"cnp_kxzxbx3cpt55\",\"linkedTopicIds\":[\"cnp_kxzxbx3cpt55\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_xzxbx3_rjb_exe5\",\"sourceBook\":\"选择性必修三\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"可见光波长 400 nm 与 760 nm 的电磁辐射的能量子 ε 分别是多少？\",\"answer\":\"利用公式 ε = hν = hc/λ，可得：ε(400 nm) ≈ 4.97×10^-19 J；ε(760 nm) ≈ 2.62×10^-19 J。\",\"explanation\":\"考查能量子公式 ε = hν = hc/λ 的应用。\",\"id\":\"cnp_kbx3cpt199_q143007\",\"topicId\":\"cnp_kbx3cpt199\",\"linkedTopicIds\":[\"cnp_kbx3cpt199\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_xzxbx3_rjb_exe7\",\"sourceBook\":\"选择性必修三\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"已知中子的质量 mn = 1.6749×10^-27 kg，质子的质量 mp = 1.6726×10^-27 kg，氘核质量 mD = 3.3436×10^-27 kg，求氘核的比结合能。\",\"answer\":\"氘核比结合能 = 1.10 MeV\",\"explanation\":\"利用质量亏损 Δm = mp + mn − mD，结合质能方程 E=mc² 求得结合能，再除以核子数。\",\"id\":\"cnp_kxzxbx3cpt138_q143011\",\"topicId\":\"cnp_kxzxbx3cpt138\",\"linkedTopicIds\":[\"cnp_kxzxbx3cpt138\",\"cnp_kxzxbx3cpt139\",\"cnp_kxzxbx3cpt137\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_xzxbx3_rjb_exe11\",\"sourceBook\":\"选择性必修三\",\"difficulty\":\"standard\"},{\"type\":\"self\",\"prompt\":\"什么是核裂变？什么是链式反应？\",\"answer\":\"核裂变是重核分裂成两个或多个中等质量原子核并释放能量的过程；链式反应是裂变产生的中子继续引发新的裂变，使反应持续进行的过程。\",\"id\":\"cnp_kxzxbx3cpt140_q143012\",\"topicId\":\"cnp_kxzxbx3cpt140\",\"linkedTopicIds\":[\"cnp_kxzxbx3cpt140\",\"cnp_k9cpt195\"],\"source\":\"k12-exercise\",\"sourceId\":\"physics_xzxbx3_rjb_exe12\",\"sourceBook\":\"选择性必修三\",\"difficulty\":\"basic\"}]");
